import bpy, os, json, urllib.parse, urllib.request
expected=os.path.normcase(os.path.normpath(r'C:\\mcp-blender\\salvador_lacerda_do_zero.blend'))
if os.path.normcase(os.path.normpath(bpy.data.filepath))!=expected:
    raise RuntimeError(f'ABORTADO arquivo errado {bpy.data.filepath!r}')
BASE='https://geo.salvador.ba.gov.br/portal/sharing/rest/search'
terms=['curva de nivel','curvas de nivel','curva nivel','altimetria','altimetrico','altimetrica','ponto cotado','pontos cotados','cota altimetrica','topografia','topografico','MDT','MDE','DEM','DTM','LiDAR','laser','nuvem de pontos','SICAD','cartografia 2017','relevo','hipsometria','declividade']
items={}
def get_json(url,params=None,timeout=20):
    if params:
        url += ('&' if '?' in url else '?') + urllib.parse.urlencode(params)
    req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'})
    with urllib.request.urlopen(req,timeout=timeout) as r:
        return json.loads(r.read().decode('utf-8','replace'))
for term in terms:
    q=f'({term}) AND (owner:GEO_* OR orgid:*)'
    try:
        data=get_json(BASE,{'q':q,'f':'json','num':100})
    except Exception as e:
        print('SEARCH_ERR',term,type(e).__name__,str(e)[:160]); continue
    print('TERM',term,'TOTAL',data.get('total',0),'RETURNED',len(data.get('results',[])))
    for it in data.get('results',[]):
        owner=str(it.get('owner',''))
        url=str(it.get('url') or '')
        title=str(it.get('title') or '')
        typ=str(it.get('type') or '')
        blob=' '.join([title,typ,url,' '.join(it.get('tags') or []),str(it.get('snippet') or '')]).lower()
        if owner.startswith('GEO_') or 'geo.salvador.ba.gov.br' in url.lower():
            items[it.get('id')]=it
print('OFFICIAL_UNIQUE',len(items))
for it in sorted(items.values(), key=lambda x:(str(x.get('owner')),str(x.get('title')))):
    slim={k:it.get(k) for k in ('id','title','type','owner','url','tags','snippet','description','access','modified')}
    print('ITEM',json.dumps(slim,ensure_ascii=False,separators=(',',':')))
    url=it.get('url')
    if isinstance(url,str) and 'geo.salvador.ba.gov.br' in url and ('FeatureServer' in url or 'MapServer' in url or 'ImageServer' in url):
        try:
            meta=get_json(url,{'f':'json'})
            ms={k:meta.get(k) for k in ('name','serviceDescription','description','currentVersion','capabilities','units','spatialReference','initialExtent','fullExtent','pixelSizeX','pixelSizeY','pixelType','minValues','maxValues')}
            layers=meta.get('layers') or []
            if layers: ms['layers']=[{k:l.get(k) for k in ('id','name','parentLayerId','subLayerIds')} for l in layers[:80]]
            print('META',json.dumps(ms,ensure_ascii=False,separators=(',',':')))
        except Exception as e:
            print('META_ERR',url,type(e).__name__,str(e)[:120])
print('ALTIMETRY_CATALOG_SEARCH_DONE')
